selector_to_html = {"a[href=\"../glossary.html#term-iaith-wrthrych-gyfeiriadol\"]": "<dt id=\"term-iaith-wrthrych-gyfeiriadol\">iaith wrthrych-gyfeiriadol</dt><dd><p>object-oriented language</p></dd>", "a[href=\"../glossary.html#term-gorlwytho-gweithredydd\"]": "<dt id=\"term-gorlwytho-gweithredydd\">gorlwytho gweithredydd</dt><dd><p>operator overloading</p></dd>", "a[href=\"../glossary.html#term-dull-enghraifft\"]": "<dt id=\"term-dull-enghraifft\">dull enghraifft</dt><dd><p>instance method</p></dd>", "a[href=\"#y-dull-str\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">15.5. </span>Y Dull <strong>str</strong><a class=\"headerlink\" href=\"#y-dull-str\" title=\"Link to this heading\">#</a></h2><p>Pan ysgrifennwch ddull, gallwch ddewis bron unrhyw enw a hoffech. Fodd\nbynnag, mae gan rai enwau ystyron arbennig. Er enghraifft, os oes gan\nwrthrych ddull o\u2019r enw <code class=\"docutils literal notranslate\"><span class=\"pre\">__str__</span></code>, mae Python yn defnyddio\u2019r dull hwnnw i\ndrosi\u2019r gwrthrych yn llinyn. Er enghraifft, dyma ddull <code class=\"docutils literal notranslate\"><span class=\"pre\">__str__</span></code> ar gyfer\ngwrthrych amser.</p>", "a[href=\"../glossary.html#term-amod-cyson\"]": "<dt id=\"term-amod-cyson\">amod cyson</dt><dd><p>invariant</p></dd>", "a[href=\"#cymharu-gwrthrychau-time\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">15.4. </span>Cymharu Gwrthrychau Time<a class=\"headerlink\" href=\"#cymharu-gwrthrychau-time\" title=\"Link to this heading\">#</a></h2><p>Fel un enghraifft arall, gadewch i ni ysgrifennu <code class=\"docutils literal notranslate\"><span class=\"pre\">is_after</span></code> fel dull. Dyma\u2019r\nswyddogaeth <code class=\"docutils literal notranslate\"><span class=\"pre\">is_after</span></code>, sy\u2019n ddatrysiad i ymarfer yn y bennod flaenorol.</p>", "a[href=\"#dosbarthiadau-a-dulliau\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">15. </span>Dosbarthiadau a Dulliau<a class=\"headerlink\" href=\"#dosbarthiadau-a-dulliau\" title=\"Link to this heading\">#</a></h1><p>Mae Python yn <strong><a class=\"reference internal\" href=\"../glossary.html#term-iaith-wrthrych-gyfeiriadol\"><span class=\"xref std std-term\">iaith wrthrych-gyfeiriadol</span></a></strong> \u2014 hynny yw, mae\u2019n\ndarparu nodweddion sy\u2019n cefnogi rhaglennu gwrthrych-gyfeiriadol, sydd \u00e2\u2019r\nnodweddion diffiniol hyn:</p>", "a[href=\"#diffinio-dulliau\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">15.1. </span>Diffinio Dulliau<a class=\"headerlink\" href=\"#diffinio-dulliau\" title=\"Link to this heading\">#</a></h2><p>Yn y bennod flaenorol diffiniom ddosbarth o\u2019r enw <code class=\"docutils literal notranslate\"><span class=\"pre\">Time</span></code> ac ysgrifennu\nswyddogaeth o\u2019r enw <code class=\"docutils literal notranslate\"><span class=\"pre\">print_time</span></code> sy\u2019n dangos amser y dydd.</p>", "a[href=\"../glossary.html#term-dull-statig\"]": "<dt id=\"term-dull-statig\">dull statig</dt><dd><p>static method</p></dd>", "a[href=\"#ymarferion\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">15.10. </span>Ymarferion<a class=\"headerlink\" href=\"#ymarferion\" title=\"Link to this heading\">#</a></h2><h3><span class=\"section-number\">15.10.1. </span>Gofyn i gynorthwyydd rhithwir<a class=\"headerlink\" href=\"#gofyn-i-gynorthwyydd-rhithwir\" title=\"Link to this heading\">#</a></h3><p>Am fwy o wybodaeth am ddulliau statig, gofynnwch i gynorthwyydd rhithwir:</p>", "a[href=\"../glossary.html#term-derbynnydd\"]": "<dt id=\"term-derbynnydd\">derbynnydd</dt><dd><p>receiver</p></dd>", "a[href=\"#gofyn-i-gynorthwyydd-rhithwir\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">15.10.1. </span>Gofyn i gynorthwyydd rhithwir<a class=\"headerlink\" href=\"#gofyn-i-gynorthwyydd-rhithwir\" title=\"Link to this heading\">#</a></h3><p>Am fwy o wybodaeth am ddulliau statig, gofynnwch i gynorthwyydd rhithwir:</p>", "a[href=\"#dull-arall\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">15.2. </span>Dull Arall<a class=\"headerlink\" href=\"#dull-arall\" title=\"Link to this heading\">#</a></h2><p>Dyma\u2019r swyddogaeth <code class=\"docutils literal notranslate\"><span class=\"pre\">time_to_int</span></code> o\u2019r bennod flaenorol.</p>", "a[href=\"../glossary.html#term-dull\"]": "<dt id=\"term-dull\">dull</dt><dd><p>method</p></dd>", "a[href=\"#rhestr-termau-r-bennod\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">15.9. </span>Rhestr Termau\u2019r Bennod<a class=\"headerlink\" href=\"#rhestr-termau-r-bennod\" title=\"Link to this heading\">#</a></h2><p><strong>iaith wrthrych-gyfeiriadol:</strong>\nIaith sy\u2019n darparu nodweddion i gefnogi rhaglennu gwrthrych-gyfeiriadol, yn\nenwedig mathau a ddiffinnir gan ddefnyddwyr.</p><p><strong>dull:</strong>\nSwyddogaeth a ddiffinnir y tu mewn i ddiffiniad dosbarth ac a elwir ar\nenghreifftiau\u2019r dosbarth hwnnw.</p>", "a[href=\"#ymarfer\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">15.10.2. </span>Ymarfer<a class=\"headerlink\" href=\"#ymarfer\" title=\"Link to this heading\">#</a></h3><p>Yn y bennod flaenorol, gofynnodd cyfres o ymarferion i chi ysgrifennu\ndosbarth <code class=\"docutils literal notranslate\"><span class=\"pre\">Date</span></code> a sawl swyddogaeth sy\u2019n gweithio gyda gwrthrychau <code class=\"docutils literal notranslate\"><span class=\"pre\">Date</span></code>.\nNawr gadewch i ni ymarfer ailysgrifennu\u2019r swyddogaethau hynny fel dulliau.</p>", "a[href=\"#dadnamu\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">15.8. </span>Dadnamu<a class=\"headerlink\" href=\"#dadnamu\" title=\"Link to this heading\">#</a></h2><p>Mae gwrthrych <code class=\"docutils literal notranslate\"><span class=\"pre\">Time</span></code> yn ddilys os yw gwerthoedd <code class=\"docutils literal notranslate\"><span class=\"pre\">minute</span></code> a <code class=\"docutils literal notranslate\"><span class=\"pre\">second</span></code> rhwng\n<code class=\"docutils literal notranslate\"><span class=\"pre\">0</span></code> a <code class=\"docutils literal notranslate\"><span class=\"pre\">60</span></code> \u2014 gan gynnwys <code class=\"docutils literal notranslate\"><span class=\"pre\">0</span></code> ond nid <code class=\"docutils literal notranslate\"><span class=\"pre\">60</span></code> \u2014 ac os yw <code class=\"docutils literal notranslate\"><span class=\"pre\">hour</span></code> yn bositif.\nHefyd, dylai <code class=\"docutils literal notranslate\"><span class=\"pre\">hour</span></code> a <code class=\"docutils literal notranslate\"><span class=\"pre\">minute</span></code> fod yn werthoedd cyfanrif, ond efallai y\ncaniatawn i <code class=\"docutils literal notranslate\"><span class=\"pre\">second</span></code> gael rhan ffracsiynol.</p><p>Gelwir gofynion fel y rhain yn **<a class=\"reference internal\" href=\"../glossary.html#term-amod-cyson\"><span class=\"xref std std-term\">amod cyson</span></a>**ion am y dylent fod\nbob amser yn wir. I\u2019w ddweud ffordd arall, os nad ydynt yn wir, mae\nrhywbeth wedi mynd o\u2019i le.</p>", "a[href=\"#dulliau-statig\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">15.3. </span>Dulliau Statig<a class=\"headerlink\" href=\"#dulliau-statig\" title=\"Link to this heading\">#</a></h2><p>Fel enghraifft arall, gadewch i ni ystyried y swyddogaeth <code class=\"docutils literal notranslate\"><span class=\"pre\">int_to_time</span></code>.\nDyma\u2019r fersiwn o\u2019r bennod flaenorol.</p>", "a[href=\"../glossary.html#term-dull-arbennig\"]": "<dt id=\"term-dull-arbennig\">dull arbennig</dt><dd><p>special method</p></dd>", "a[href=\"#gorlwytho-gweithredydd\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">15.7. </span>Gorlwytho Gweithredydd<a class=\"headerlink\" href=\"#gorlwytho-gweithredydd\" title=\"Link to this heading\">#</a></h2><p>Drwy ddiffinio dulliau arbennig eraill, gallwch nodi ymddygiad\ngweithredyddion ar fathau a ddiffinnir gan raglenwyr. Er enghraifft, os\ndiffiniwch ddull o\u2019r enw <code class=\"docutils literal notranslate\"><span class=\"pre\">__add__</span></code> ar gyfer y dosbarth <code class=\"docutils literal notranslate\"><span class=\"pre\">Time</span></code>, gallwch\nddefnyddio\u2019r gweithredydd <code class=\"docutils literal notranslate\"><span class=\"pre\">+</span></code> ar wrthrychau Time.</p><p>Dyma ddull <code class=\"docutils literal notranslate\"><span class=\"pre\">__add__</span></code>.</p>", "a[href=\"#y-dull-init\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">15.6. </span>Y Dull init<a class=\"headerlink\" href=\"#y-dull-init\" title=\"Link to this heading\">#</a></h2><p>Y mwyaf arbennig o\u2019r dulliau arbennig yw <code class=\"docutils literal notranslate\"><span class=\"pre\">__init__</span></code>, a elwir felly am ei\nfod yn cychwyn priodoleddau gwrthrych newydd. Gallai dull <code class=\"docutils literal notranslate\"><span class=\"pre\">__init__</span></code> ar\ngyfer y dosbarth <code class=\"docutils literal notranslate\"><span class=\"pre\">Time</span></code> edrych fel hyn:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
